//! Cargo-driven `riched20.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The module is C, compiled and linked by reactos-link: there is no Rust body.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DllMainCRTStartup@12", Some(0x78c10000u64)),
        "x86_64" => ("x86_64-pc-windows-gnu", "DllMainCRTStartup", Some(0x7ff8c000000u64)),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DllMainCRTStartup", Some(0x7ff8c000000u64)),
        o => panic!("riched20-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["engine:wine", "engine:uuid", "engine:oldnames", "import:ole32", "import:oleaut32", "import:usp10", "import:imm32", "import:user32", "import:gdi32", "import:msvcrt", "import:kernel32", "import:ntdll", "body"],
        "x86_64" => &["engine:wine", "engine:uuid", "engine:oldnames", "import:ole32", "import:oleaut32", "import:usp10", "import:imm32", "import:user32", "import:gdi32", "import:msvcrt", "import:kernel32", "import:ntdll", "body"],
        "aarch64" => &["engine:wine", "engine:uuid", "engine:oldnames", "import:ole32", "import:oleaut32", "import:usp10", "import:imm32", "import:user32", "import:gdi32", "import:msvcrt", "import:kernel32", "import:ntdll", "body"],
        _ => unreachable!(),
    };

    // The module's part of cmake's windres command; reactos-link adds what every
    // module shares from reactos-link/cflags/rc.<arch>.flags (Linker::rc).
    let rc_includes: &[&str] = &[
        "@build/dll/win32/riched20",
        "dll/win32/riched20",
        "@build/sdk/include/wine",
        "sdk/include/wine",
        "@std",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
        "sdk/lib/pseh/include",
        "sdk/lib/tdilib",
        "vendor/zlib/include",
        "vendor/libtiff/include",
    ];
    let rc_flags: &[&str] = &[];
    let rc_defines: &[&str] = &[
        "WINVER=0x502",
        "_CRT_DECLARE_NONSTDC_NAMES=1",
        "_CRT_NONSTDC_NO_DEPRECATE",
        "_DLL",
        "_WIN32_WINNT=0x502",
        "__USE_CRTIMP",
        "__WINESRC__",
    ];

    Linker::new(target_json)
        .c_from_compile_db("riched20_shims", &["dll/win32/riched20/caret.c", "dll/win32/riched20/clipboard.c", "dll/win32/riched20/context.c", "dll/win32/riched20/editor.c", "dll/win32/riched20/list.c", "dll/win32/riched20/paint.c", "dll/win32/riched20/para.c", "dll/win32/riched20/reader.c", "dll/win32/riched20/richole.c", "dll/win32/riched20/row.c", "dll/win32/riched20/run.c", "dll/win32/riched20/string.c", "dll/win32/riched20/style.c", "dll/win32/riched20/table.c", "dll/win32/riched20/txthost.c", "dll/win32/riched20/txtsrv.c", "dll/win32/riched20/undo.c", "dll/win32/riched20/wrap.c", "dll/win32/riched20/writer.c"])
        .rc("dll/win32/riched20/version.rc", rc_includes, rc_flags, rc_defines)
        .spec2def("dll/win32/riched20/riched20.spec", "riched20.dll")
        .import_lib("dll/win32/ole32/ole32.spec", "ole32.dll", "ole32")
        .import_lib("dll/win32/oleaut32/oleaut32.spec", "oleaut32.dll", "oleaut32")
        .import_lib("dll/win32/usp10/usp10.spec", "usp10.dll", "usp10")
        .import_lib("win32ss/user/imm32/imm32.spec", "imm32.dll", "imm32")
        .import_lib("win32ss/user/user32/user32.spec", "user32.dll", "user32")
        .import_lib("win32ss/gdi/gdi32/gdi32.spec", "gdi32.dll", "gdi32")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .msvcrtex_crt(MsvcrtexKind::Dll)
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
